DECLARE
  v_recipient uuid;
  v_phase_label text;
BEGIN
  IF NEW.operacao_mode IS DISTINCT FROM OLD.operacao_mode THEN
    v_phase_label := CASE NEW.operacao_mode
      WHEN 'planning' THEN 'Planeamento'
      WHEN 'montagem' THEN 'Montagem'
      WHEN 'evento'   THEN 'Evento'
      WHEN 'post'     THEN 'Pós-Evento'
      ELSE COALESCE(NEW.operacao_mode, 'SETUP')
    END;

    FOR v_recipient IN
      SELECT DISTINCT profile_id FROM public.event_team_members
      WHERE event_id = NEW.id AND role IN ('director','general_producer')
    LOOP
      PERFORM public.enqueue_whatsapp_notification(
        'fase_evento_avancou', v_recipient,
        jsonb_build_array(COALESCE(NEW.name,''), v_phase_label),
        NEW.id, 'event', NEW.id
      );
    END LOOP;

    FOR v_recipient IN
      SELECT DISTINCT current_lead_id FROM public.operacao_frentes
      WHERE event_id = NEW.id AND current_lead_id IS NOT NULL
        AND current_lead_id NOT IN (
          SELECT profile_id FROM public.event_team_members
          WHERE event_id = NEW.id AND role IN ('director','general_producer')
        )
    LOOP
      PERFORM public.enqueue_whatsapp_notification(
        'fase_evento_avancou', v_recipient,
        jsonb_build_array(COALESCE(NEW.name,''), v_phase_label),
        NEW.id, 'event', NEW.id
      );
    END LOOP;
  END IF;
  RETURN NEW;
END

DECLARE
  r RECORD;
BEGIN
  IF NEW.event_id IS NOT DISTINCT FROM OLD.event_id THEN RETURN NULL; END IF;
  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;

  FOR r IN
    SELECT f.id, f.event_id, f.company_id
      FROM public.event_forecasts f
     WHERE f.transaction_id = NEW.id
       AND f.version_id IS NULL
  LOOP
    IF public.bp_tx_link_allowed(NEW.event_id, NEW.company_id, r.event_id, r.company_id) THEN
      CONTINUE;
    END IF;

    UPDATE public.event_forecasts SET transaction_id = NULL WHERE id = r.id;

    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id)
    VALUES ('transaction', NEW.id, 'auto_unlink_forecast_tx_event_change', 'sistema (trigger)',
            jsonb_build_object('forecast_transaction_id', NEW.id),
            jsonb_build_object('forecast_transaction_id', NULL),
            jsonb_build_object('forecast_id', r.id, 'old_event_id', OLD.event_id, 'new_event_id', NEW.event_id,
                               'forecast_event_id', r.event_id, 'source', 'trigger'),
            COALESCE(NEW.company_id, r.company_id));
  END LOOP;

  RETURN NULL;
END

DECLARE v_row public.event_settlements;
BEGIN
  IF NOT has_permission(auth.uid(),'manage_bp') THEN
    RAISE EXCEPTION 'Sem permissão para reabrir fechamentos';
  END IF;
  IF _reason IS NULL OR btrim(_reason) = '' THEN
    RAISE EXCEPTION 'É obrigatório indicar o motivo da reabertura';
  END IF;

  SELECT * INTO v_row FROM public.event_settlements WHERE id = _settlement_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Fechamento % não existe', _settlement_id; END IF;
  IF v_row.company_id <> current_company_id() THEN RAISE EXCEPTION 'Fechamento de outra empresa'; END IF;
  IF NOT v_row.is_sealed THEN RAISE EXCEPTION 'Este fechamento não está selado'; END IF;

  PERFORM set_config('app.settlement_seal_op', 'on', true);

  UPDATE public.event_settlements SET
    is_sealed = false,
    sealed_snapshot = NULL,
    unsealed_at = now(),
    unsealed_by = auth.uid(),
    unseal_reason = btrim(_reason)
  WHERE id = _settlement_id;

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, company_id)
  VALUES ('event_settlements', _settlement_id::text, 'settlement_unsealed', COALESCE(auth.uid()::text,'system'),
          jsonb_build_object('sealed_at', v_row.sealed_at, 'sealed_by', v_row.sealed_by,
                             'sealed_bp_version_id', v_row.sealed_bp_version_id),
          jsonb_build_object('reason', btrim(_reason)),
          v_row.company_id);

  RETURN jsonb_build_object('ok', true, 'settlement_id', _settlement_id);
END

